std::string hay = FUZZ_PARAM_STR(); if (hay.size() > 1024) hay.resize(1024);
std::string nee = FUZZ_PARAM_STR(); if (nee.size() > 256) nee.resize(256);

// Call target; some platforms declare/implement strcasestr with const-correct return
const char *p = strcasestr(hay.c_str(), nee.c_str());

// Property: for empty needle, common semantics return haystack pointer
if (nee.empty()) {
    FUZZ_ASSERT(p == hay.c_str(), "Empty needle should return haystack pointer");
}

// If a match is reported and needle is non-empty, validate case-insensitive equality of the slice
if (p && !nee.empty()) {
    size_t off = (size_t)(p - hay.c_str());
    if (off <= hay.size() && nee.size() <= hay.size() - off) {
        std::string seg = hay.substr(off, nee.size());
        for (char &c : seg) { if (c >= 'A' && c <= 'Z') c = (char)(c - 'A' + 'a'); }
        std::string neel = nee; for (char &c : neel) { if (c >= 'A' && c <= 'Z') c = (char)(c - 'A' + 'a'); }
        FUZZ_ASSERT(seg == neel, "Match region must equal needle under case-insensitive comparison");
    }
